+  grid-template-columns:280px 1fr;
+  gap:16px;
+  align-items:start;
+}
+.sidebar{
+  position:sticky;
+  top:72px;
+  border:1px solid var(--border);
+  border-radius:var(--radius);
+  background:rgba(2,6,23,.18);
