+.docs-main ul{margin:0 0 10px;padding-left:18px;color:var(--muted2);line-height:1.75}
+
+.sidebar-collapsed .docs{grid-template-columns:72px 1fr}
+.sidebar-collapsed .sidebar nav .side-text{display:none}
+.sidebar-collapsed .sidebar{border-radius:20px}
+.sidebar-collapsed .sidebar header strong{display:none}
+
+.tag{
+  display:inline-flex;align-items:center;gap:8px;
+  font-family:var(--mono);
+  font-size:12px;
+  padding:7px 10px;
+  border-radius:999px;
+  border:1px solid rgba(148,163,184,.18);
+  background:rgba(15,23,42,.28);
+  color:var(--muted2);
+}
+
+.diagram{border:1px dashed rgba(148,163,184,.22);border-radius:var(--radius);padding:14px;background:rgba(2,6,23,.16)}
+.diagram-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-top:10px}
+.actor{border:1px solid var(--border);border-radius:16px;padding:12px;background:rgba(15,23,42,.30)}
+.actor .k{font-family:var(--mono);font-size:12px;color:#eafff4}
+.actor .d{margin-top:6px;color:var(--muted2);font-size:13px;line-height:1.55}
+
+.status{
+  display:inline-flex;align-items:center;gap:8px;
+  padding:6px 10px;border-radius:999px;
+  border:1px solid rgba(251,113,133,.28);
+  background:rgba(251,113,133,.08);
+  color:#fecdd3;font-size:12px;
+}
+
+/* Utilities */
+.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
+.flex{display:flex}
+.between{justify-content:space-between}
+.center{align-items:center}
+.mt8{margin-top:8px}
+.mt12{margin-top:12px}
+.mt16{margin-top:16px}
+.mt20{margin-top:20px}
+.mt24{margin-top:24px}
+.muted{color:var(--muted2)}
+
+/* Responsive */
+@media (max-width: 980px){
+  .hero-grid{grid-template-columns:1fr}
+  .hero h2{font-size:40px}
+  .cli{grid-template-columns:1fr}
+  .grid-3{grid-template-columns:1fr}
+  .grid-4{grid-template-columns:repeat(2,1fr)}
+  .footer-grid{grid-template-columns:repeat(2,1fr)}
+  .docs{grid-template-columns:1fr}
+  .sidebar{position:relative;top:auto}
+}
+@media (max-width: 560px){
+  .hero{padding:44px 0 18px}
+  .hero h2{font-size:34px}
+  .grid-4{grid-template-columns:1fr}
+  .footer-grid{grid-template-columns:1fr}
+  .topbar-inner{flex-wrap:wrap}
+  .nav{gap:12px}
+}
+
*** End Patch
